    /// <summary>Fills gf_control_hooks: an entry for each hook in overridden.</summary>
    internal static unsafe void fill_control_segment(gf_control_hooks* segment, HookSet overridden)
    {
        (*segment).struct_size = (uint)sizeof(gf_control_hooks);
        (*segment).class_id = Constants.GF_CLASS_CONTROL;
        if (overridden.contains(HookKeys.control_on_auto_size_changed))
        {
            (*segment).on_auto_size_changed = &OnAutoSizeChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_back_color_changed))
        {
            (*segment).on_back_color_changed = &OnBackColorChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_causes_validation_changed))
        {
            (*segment).on_causes_validation_changed = &OnCausesValidationChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_cursor_changed))
        {
            (*segment).on_cursor_changed = &OnCursorChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_dock_changed))
        {
            (*segment).on_dock_changed = &OnDockChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_enabled_changed))
        {
            (*segment).on_enabled_changed = &OnEnabledChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_fore_color_changed))
        {
            (*segment).on_fore_color_changed = &OnForeColorChangedEntry;
        }
        if (overridden.contains(HookKeys.control_on_margin_changed))
        {
            (*segment).on_margin_changed = &OnMarginChangedEntry;
        }
